B.a2p=s(["Rilekskan wajah","Berkedip penuh dan perlahan","Biarkan mata beristirahat"],t.s)
B.a9w=s(["Tutup mata ringan","Rilekskan wajah dan bahu","Buka perlahan saat diberi isyarat"],t.s)
B.XJ=s(["Lihat titik yang jauh","Jaga pandangan di luar layar","Berkedip sebelum kembali"],t.s)
B.a8m=s(["Berpaling dari layar","Lihat ke seberang ruangan","Biarkan bahu turun"],t.s)
B.a_e=s(["Kurangi silau jika perlu","Jaga layar sepanjang lengan","Buat teks nyaman"],t.s)
B.aaS=s(["Lepaskan rahang","Turunkan bahu","Jaga pandangan di luar layar"],t.s)
B.Zy=s([u.m2,u.uw,u.ci],t.s)
B.V5=s(["Cek pantulan jendela atau lampu pada layar.",u.lM,u.AR],t.s)
