B.aar=s([u.yO,"\u0417\u0431\u0456\u043b\u044c\u0448\u0442\u0435 \u0440\u043e\u0437\u043c\u0456\u0440 \u0442\u0435\u043a\u0441\u0442\u0443, \u044f\u043a\u0449\u043e \u0432\u0430\u043c \u0434\u043e\u0432\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u043d\u0430\u0445\u0438\u043b\u044f\u0442\u0438\u0441\u044f \u0431\u043b\u0438\u0436\u0447\u0435.","\u0422\u0440\u0438\u043c\u0430\u0439\u0442\u0435 \u0432\u0435\u0440\u0445\u043d\u0456\u0439 \u043a\u0440\u0430\u0439 \u0435\u043a\u0440\u0430\u043d\u0430 \u043d\u0430 \u0440\u0456\u0432\u043d\u0456 \u043e\u0447\u0435\u0439 \u0430\u0431\u043e \u0442\u0440\u043e\u0445\u0438 \u043d\u0438\u0436\u0447\u0435."],t.s)
B.Zr=s(["\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435, \u0447\u0438 \u043d\u0435 \u0432\u0456\u0434\u0431\u0438\u0432\u0430\u044e\u0442\u044c\u0441\u044f \u043d\u0430 \u0435\u043a\u0440\u0430\u043d\u0456 \u0432\u0456\u043a\u043d\u043e \u0430\u0431\u043e \u043b\u0430\u043c\u043f\u0430.","\u041f\u0435\u0440\u0435\u043c\u0456\u0441\u0442\u0456\u0442\u044c \u0435\u043a\u0440\u0430\u043d \u0430\u0431\u043e \u0434\u0436\u0435\u0440\u0435\u043b\u043e \u0441\u0432\u0456\u0442\u043b\u0430, \u0449\u043e\u0431 \u0437\u043c\u0435\u043d\u0448\u0438\u0442\u0438 \u0432\u0456\u0434\u0431\u043b\u0438\u0441\u043a\u0438.","\u0423\u043d\u0438\u043a\u0430\u0439\u0442\u0435 \u043d\u0430\u0434\u0442\u043e \u044f\u0441\u043a\u0440\u0430\u0432\u043e\u0433\u043e \u0435\u043a\u0440\u0430\u043d\u0430 \u0432 \u0442\u0435\u043c\u043d\u0456\u0439 \u043a\u0456\u043c\u043d\u0430\u0442\u0456."],t.s)
