B.Vy=s(["\u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u043d\u0430 \u0434\u0430\u043b\u044c\u043d\u044e\u044e \u0442\u043e\u0447\u043a\u0443","\u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u0432\u0437\u0433\u043b\u044f\u0434 \u0432\u043d\u0435 \u044d\u043a\u0440\u0430\u043d\u0430","\u041c\u043e\u0440\u0433\u043d\u0438\u0442\u0435 \u043f\u0435\u0440\u0435\u0434 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435\u043c"],t.s)
B.a_P=s(["\u041e\u0442\u0432\u0435\u0440\u043d\u0438\u0442\u0435\u0441\u044c \u043e\u0442 \u044d\u043a\u0440\u0430\u043d\u0430","\u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u0432 \u0434\u0430\u043b\u044c\u043d\u0438\u0439 \u0443\u0433\u043e\u043b \u043a\u043e\u043c\u043d\u0430\u0442\u044b","\u0420\u0430\u0441\u0441\u043b\u0430\u0431\u044c\u0442\u0435 \u043f\u043b\u0435\u0447\u0438"],t.s)
B.a9O=s(["\u0423\u043c\u0435\u043d\u044c\u0448\u0438\u0442\u0435 \u0431\u043b\u0438\u043a\u0438, \u0435\u0441\u043b\u0438 \u043d\u0443\u0436\u043d\u043e","\u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u044d\u043a\u0440\u0430\u043d \u043d\u0430 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0438 \u0432\u044b\u0442\u044f\u043d\u0443\u0442\u043e\u0439 \u0440\u0443\u043a\u0438","\u0421\u0434\u0435\u043b\u0430\u0439\u0442\u0435 \u0442\u0435\u043a\u0441\u0442 \u0443\u0434\u043e\u0431\u043d\u044b\u043c \u0434\u043b\u044f \u0447\u0442\u0435\u043d\u0438\u044f"],t.s)
